from pathlib import Path
import json,html
root=Path(__file__).resolve().parents[1]
notes={
'song':('歌曲详情','曲名占满可用行宽；五个难度改为轻量页签；谱面保留主面板，成绩与交流改为无底色侧栏。','元数据与曲名保持成组；难度和谱面之间单独留出切换后的停顿。手机保留完整曲名与 14px 元数据，没有为首屏压小文字。'),
 'training':('练习','移除英文眉题和常驻四步提示；目标改为摘要；更换、取消、基线与导出参数按需展开。','推荐紧跟目标；目标与推荐之间用分隔线及 28–32px 间距换题，曲目内部仅保留紧凑的标题、难度、成绩关系。'),
 'home':('首页 / My Taiko','身份只在问候与账号行表达一次；撤去目标 Hero，最近变化先于目标，推荐仍保留三个结果。','最近记录与目标为并列主题；手机先读具体变化再看目标，推荐会下移，这是本方案的取舍。'),
 'progress':('成长档案','三层近义标题合为一条带日期和数值的变化摘要；去掉图表的泛化标题；里程碑随内容自然结束。','曲线拥有主要白色阅读面；具体变化独立列出，能力数值直接展示，不用空白面板补齐高度。')}
css='''*{box-sizing:border-box}body{margin:0;background:#edf2f3;color:#1b3440;font:16px/1.7 system-ui,"Noto Sans CJK SC",sans-serif}header,main{max-width:1560px;margin:auto;padding:28px 28px 0}h1{font-size:28px;line-height:1.4;margin:0 0 12px}h2{font-size:21px;margin:0}h3{font-size:17px;margin:0}p{margin:8px 0 16px}a{color:#007985;text-underline-offset:4px}button,select{font:inherit;min-height:44px;border:1px solid #879ba4;background:white;color:inherit;border-radius:5px;padding:7px 12px}button{cursor:pointer}nav{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:20px 0}button[aria-pressed=true]{background:#1b3440;color:white}.note{max-width:90ch}.meta{font-size:14px;color:#46616e}.pair{display:grid;grid-template-columns:1fr 1fr;gap:24px;align-items:start;margin:20px 0 40px}.pair figure{margin:0;min-width:0}.pair figcaption{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;gap:12px;font-size:15px}.pair img{display:block;width:100%;height:auto;border:0;outline:1px solid #ced9de}.pair.phone{grid-template-columns:390px 390px;justify-content:center}.pair.phone img{width:390px;max-width:100%}.links{display:flex;gap:20px;flex-wrap:wrap;margin:10px 0 28px}.review-points{border-top:1px solid #c6d3d9;padding-top:20px;margin-bottom:35px}.sources{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:32px;align-items:start;margin:20px 0 60px}.sources.phone{grid-template-columns:390px minmax(0,650px);justify-content:center}.annotated{position:relative;line-height:0}.annotated img{width:100%;height:auto}.mark{position:absolute;border:2px dashed #922e20;pointer-events:none;background:#fff6}.mark b{position:absolute;left:0;top:0;border:2px solid white;background:#922e20;color:white;min-width:28px;min-height:28px;display:grid;place-items:center;font:700 16px/1 system-ui;border-radius:50%;transform:translate(-10%,-45%)}.annotation-list{margin:0;padding-left:24px}.annotation-list li{margin-bottom:22px}.annotation-list strong{display:block}.raw{display:block;margin:15px 0}footer{padding:10px 28px 40px;max-width:1560px;margin:auto;font-size:14px;color:#46616e}@media(max-width:900px){header,main{padding:20px 16px 0}.pair,.pair.phone,.sources,.sources.phone{grid-template-columns:minmax(0,1fr)}.pair.phone figure{width:390px;max-width:100%;margin:auto}.sources.phone .annotated{max-width:390px}.sources{gap:20px}}'''
head=f'<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>{css}</style>'
(root/'compare.html').write_text(head+'''<title>Viewer V1 / V2 · 同视口对照</title></head><body><header><p class="meta">Viewer 产品设计 · 2026-10-20 · 视觉方向待评审</p><h1>让内容成组，让阅读有停顿。</h1><p class="note">两侧均为同一份合成玩家数据、相同曲目、中文、正常状态和 DPR 1。截图隐藏评审栏，保留产品导航；没有用不同视口或裁切美化 V2。</p><div class="links"><a href="v2/index.html?view=song">打开可操作 V2</a><a href="v1/index.html?view=song">打开保留 V1</a><a href="references.html">pjsk.moe 实拍与标注</a><a href="README.md">修订说明</a></div><nav aria-label="选择页面" id="pages"></nav><nav aria-label="选择视口"><button data-width="1440" aria-pressed="true">1440 × 1000 桌面</button><button data-width="390" aria-pressed="false">390 × 844 手机</button></nav></header><main><h2 id="name"></h2><p id="change" class="note"></p><p><a id="export" href="screenshots/song-1440-compare.png">打开原尺寸左右并排图</a></p><div class="pair" id="pair"></div><div class="review-points"><h3>留白用于什么</h3><p id="space" class="note"></p><p class="meta">点击截图查看原始像素。完整长页由 Chromium 直接截取，固定手机底栏会停留在原视口位置；首屏对照以本页显示的标准视口截图为准。可操作页面可自然滚动。</p></div></main><footer>这是审美评审材料。页面是否更舒服，由布局、主次与阅读节奏判断；技术检查仅确认原型能够浏览和操作。</footer><script>const pages='''+json.dumps(notes,ensure_ascii=False)+''';let selected='song',width=1440;const nav=document.querySelector('#pages');for(const [key,value] of Object.entries(pages)){const b=document.createElement('button');b.textContent=value[0];b.dataset.page=key;nav.append(b)}function render(){const [name,change,space]=pages[selected];document.querySelector('#name').textContent=name;document.querySelector('#change').textContent=change;document.querySelector('#space').textContent=space;document.querySelector('#export').href=`screenshots/${selected}-${width}-compare.png`;document.querySelectorAll('[data-page]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.page===selected)));document.querySelectorAll('[data-width]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.width)===width)));const pair=document.querySelector('#pair');pair.className='pair'+(width===390?' phone':'');pair.innerHTML=['v1','v2'].map(v=>{const stem=`screenshots/${selected}-${width}-${v}`;return `<figure><figcaption><strong>${v.toUpperCase()} · ${width} × ${width===390?844:1000}</strong><span><a href="${v}/index.html?view=${selected}">操作</a> · <a href="${stem}-full.png">长页</a></span></figcaption><a href="${stem}.png"><img src="${stem}.png" alt="${name} ${v.toUpperCase()} ${width} 原始视口截图"></a></figure>`}).join('')}document.addEventListener('click',e=>{const p=e.target.closest('[data-page]'),w=e.target.closest('[data-width]');if(p)selected=p.dataset.page;if(w)width=Number(w.dataset.width);if(p||w)render()});render();</script></body></html>''')
references=[
('home',1440,1000,'首页：主题间留白，组内集中',[(24.4,45.8,71.2,7.5,'轮播与「最新」之间有独立停顿','借鉴主题切换的节奏。Viewer 用 28–44px 的主题间距换题，不复制轮播或扩大 Hero。'),(24.4,70,71.2,25.2,'组标题贴近所属内容','「最新卡牌」与卡片行共享左边线；标题到内容的距离小于上个主题到本组的距离。Viewer 推荐标题和结果作为同一组。'),(17.8,9.2,6.5,83,'导航与正文有独立边界','左栏与主内容保持连续分隔。Viewer 延续原导航，不把每一层正文都包进卡片。')]),
('music',1440,1000,'音乐图鉴：入口精简，内容开始得早',[(21.7,9.4,60,10.8,'一个标题组说明当前页面','数据库眉题、名称、简短说明集中在一起；下方直接进入内容。Viewer 练习页删掉重复英文眉题和四步流程，避免连续开场。'),(21.7,20.2,76.6,2,'标题组到列表的换段留白','说明结束后只有一次明确间隔，没有额外欢迎卡或功能说明面板。'),(21.7,22.2,10,26.9,'封面、名称、元信息属于一个对象','卡片内信息更紧，卡片间独立。只借鉴对象分组；七列密度、截断长标题与彩色难度徽标不作为 Viewer 标准。')]),
('home',390,844,'手机首页：沿同一条内容轴逐组展开',[(4.1,43.8,91.8,9.1,'轮播结束后再进入新主题','桌面主题的切换关系在手机上仍成立；不是把所有组件等距竖排。'),(4.1,72.4,91.8,4.2,'组标题与下一排卡片紧邻','「最新卡牌」承接卡片行；单行标签不再承担另一个大标题。'),(4.1,58.8,91.8,10.8,'空状态本身也占空间','这块空白是活动空状态容器，不作为值得复制的呼吸感。Viewer 不为无内容状态制造高白卡。')]),
('music',390,844,'手机音乐图鉴：说明一次，随后交给内容',[(4.1,15.1,91.8,13.4,'一个标题与说明组','主名称的字号突出，解释集中于其下。Viewer 用一条事实摘要承接成长图表。'),(4.1,28.5,91.8,2.1,'说明与内容之间有单次停顿','留白的作用是切换阅读对象，后续连续重复的卡片采用较紧行距。'),(4.1,30.6,44.4,35.3,'封面优先，文字跟随对象','两列卡片内围绕同一歌曲组织。Viewer 保持自己的谱面和成绩布局，不复制品牌、卡绘或两列组件。')])]
parts=[]
for page,w,h,title,marks in references:
 stem=f'moe-{page}-{w}'
 overlays=''.join(f'<span class="mark" style="left:{x}%;top:{y}%;width:{ww}%;height:{hh}%"><b>{i+1}</b></span>' for i,(x,y,ww,hh,_,_) in enumerate(marks))
 captions=''.join(f'<li><strong>{html.escape(t)}</strong>{html.escape(body)}</li>' for _,_,_,_,t,body in marks)
 url='https://pjsk.moe/zh-cn/'+('music/' if page=='music' else '')
 parts.append(f'<section id="{stem}"><h2>{title}</h2><p class="meta">{w} × {h} · <a href="{url}">{url}</a> · 2026-10-20，Asia/Shanghai</p><div class="sources'+(' phone' if w==390 else '')+f'"><div class="annotated"><img src="references/{stem}.png" alt="pjsk.moe {page} {w} 实际浏览器截图">{overlays}</div><div><ol class="annotation-list">{captions}</ol><a class="raw" href="references/{stem}.png">打开未标注原始截图</a><a class="raw" href="references/{stem}-annotated.png">打开原视口编号标注图</a></div></div></section>')
(root/'references.html').write_text(head+'''<title>pjsk.moe · 分组、留白与主次参考</title></head><body><header><p class="meta">参考实拍 · 和 Viewer 对照相同的两组视口</p><h1>借鉴信息关系，不借用品牌视觉。</h1><p class="note">以下四张为真实 Chromium 截图，1440 × 1000 与 390 × 844，DPR 1。虚线与编号是本评审页覆盖的标注，原始 PNG 保持原样；首页画面保留了当时的设置提示、空活动和轮播状态。两次视口访问的轮播内容不同，因此不据此比较素材或跨视口像素差异。</p><div class="links"><a href="compare.html">返回 Viewer V1 / V2</a><a href="references/capture.json">采集记录</a></div></header><main>'''+''.join(parts)+'''</main><footer>截图仅用于设计分析。未下载 pjsk.moe 品牌素材放入 Viewer 原型；原型继续使用原交付中的太鼓公开曲目图片及合成玩家数据。</footer></body></html>''')
print('Built compare.html and references.html')
